function atlasAssetSrc(asset?: string) {
  if (!asset) return undefined;
  const basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "";
  if (!basePath || asset === basePath || asset.startsWith(basePath + "/")) return asset;
  return basePath + (asset.startsWith("/") ? asset : "/" + asset);
}

function Hit({ id, d, label, fill = "#cfe0ef", selected, hovered, onSelect, onHover }: { id: string; d: string; label: string; fill?: string } & Pick<MapProps,"selected"|"hovered"|"onSelect"|"onHover">) {
  const active = selected === id || hovered === id;
  return <path d={d} data-structure-id={id} data-view-id={HIT_VIEW[id] ?? "whole-neuraxis"} data-source-ids={HIT_SOURCES[HIT_VIEW[id] ?? ""] ?? "terminologia-neuro"} tabIndex={0} role="button" aria-label={label} onMouseEnter={() => onHover(id)} onMouseLeave={() => onHover()} onFocus={() => onHover(id)} onBlur={() => onHover()} onClick={() => onSelect(id)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onSelect(id); } }} fill={active ? "#14b8a6" : fill} fillOpacity={active ? .55 : 0} stroke={active ? "#0f766e" : "transparent"} strokeWidth={active ? 3 : 1.2} className="cursor-pointer outline-none" />;
}
function Frame({ children, label, asset }: { children: ReactNode; label: string; asset?: string }) {
  const src = atlasAssetSrc(asset);
  return <svg viewBox="0 0 1000 680" className="block h-full min-h-[520px] w-full select-none" role="img" aria-label={label}><defs><pattern id="ng" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#dce7f2" strokeWidth=".7" /></pattern><linearGradient id="brain" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#edf3f8"/><stop offset="1" stopColor="#a9bbcf"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="3" stdDeviation="4" floodOpacity=".14"/></filter></defs><rect width="1000" height="680" fill="#fbfdff"/><rect width="1000" height="680" fill="url(#ng)" opacity=".7"/>{src?<image href={src} width="1000" height="680" preserveAspectRatio="xMidYMid meet" pointerEvents="none"/>:null}{children}</svg>;
}
function Labels({ items }: { items: Array<[number,number,string]> }) { return <g className="pointer-events-none">{items.map(([x,y,t]) => <text key={`${x}${y}`} x={x} y={y} fill="#49627c" fontSize="15" fontWeight="600">{t}</text>)}</g>; }
